Assumed stack: Node + Express + Redis (`ioredis`). Cache-aside, TTL, invalidate on write.

```js
// cache.js
import Redis from "ioredis";
const redis = new Redis(process.env.REDIS_URL);

const TTL = 300; // seconds
const key = (id) => `user:profile:${id}`;

export async function getProfile(id, loadFromDb) {
  try {
    const hit = await redis.get(key(id));
    if (hit) return JSON.parse(hit);
  } catch (e) {
    console.warn("cache read failed", e); // fall through to DB
  }
  const profile = await loadFromDb(id);
  if (profile) {
    redis.set(key(id), JSON.stringify(profile), "EX", TTL).catch(() => {});
  }
  return profile;
}

export const invalidateProfile = (id) => redis.del(key(id)).catch(() => {});
```

```js
// routes.js
import { getProfile, invalidateProfile } from "./cache.js";

app.get("/users/:id/profile", async (req, res) => {
  const profile = await getProfile(req.params.id, db.users.findProfile);
  if (!profile) return res.sendStatus(404);
  res.set("Cache-Control", "private, max-age=60").json(profile);
});

app.put("/users/:id/profile", async (req, res) => {
  const updated = await db.users.updateProfile(req.params.id, req.body);
  await invalidateProfile(req.params.id); // after DB commit, not before
  res.json(updated);
});
```

Gotchas: Redis down → falls back to DB, not a 500. Invalidate *after* commit, else a concurrent read can re-cache stale data. `private` header keeps shared CDNs from serving one user's profile to another. Cache only public profile fields, never tokens or password hashes.

